'use strict';

var constants = require('@toruslabs/constants');
var eccrypto = require('@toruslabs/eccrypto');
var metadataHelpers = require('@toruslabs/metadata-helpers');
var stringify = require('json-stable-stringify');
var common = require('./common.js');
var metadataUtils = require('./metadataUtils.js');

function isV2NonceResult(r) {
  if (!r) return false;
  return r.pubNonce !== undefined || r.typeOfUser === "v2";
}
function stripHexPrefix(str) {
  return str.startsWith("0x") ? str.slice(2) : str;
}
function toChecksumAddress(hexAddress) {
  const address = stripHexPrefix(hexAddress).toLowerCase();
  const hash = metadataHelpers.keccak256(metadataHelpers.utf8ToBytes(address), {
    prefixed: false
  });
  let ret = "0x";
  for (let i = 0; i < address.length; i++) {
    if (parseInt(hash[i], 16) >= 8) {
      ret += address[i].toUpperCase();
    } else {
      ret += address[i];
    }
  }
  return ret;
}
const generateEd25519KeyData = async ed25519Seed => {
  const ed25519Curve = metadataHelpers.getKeyCurve(constants.KEY_TYPE.ED25519);
  const N = ed25519Curve.Point.CURVE().n;
  const finalEd25519Key = metadataHelpers.getEd25519ExtendedPublicKey(ed25519Seed);
  const encryptionKey = metadataHelpers.getSecpKeyFromEd25519(finalEd25519Key.scalar);
  const encPubKeyBytes = metadataHelpers.getSecp256k1().Point.fromAffine(encryptionKey.point).toBytes(true);
  const encryptedSeed = await eccrypto.encrypt(encPubKeyBytes, ed25519Seed);
  const encData = {
    enc_text: metadataHelpers.bytesToHex(encryptedSeed.ciphertext),
    metadata: common.encParamsBufToHex(encryptedSeed),
    public_key: metadataHelpers.bytesToHex(metadataHelpers.encodeEd25519Point(finalEd25519Key.point))
  };
  const encDataBase64 = metadataHelpers.bytesToBase64(metadataHelpers.utf8ToBytes(JSON.stringify(encData)));
  const metadataPrivNonce = metadataHelpers.bytesToNumberBE(metadataHelpers.generatePrivateKey(constants.KEY_TYPE.ED25519));
  const oauthKey = metadataHelpers.mod(finalEd25519Key.scalar - metadataPrivNonce, N);
  const oauthPub = metadataHelpers.derivePubKey(ed25519Curve, oauthKey);
  const metadataSigningKey = metadataHelpers.getSecpKeyFromEd25519(oauthKey);
  return {
    oAuthKeyScalar: oauthKey,
    oAuthPubX: oauthPub.x,
    oAuthPubY: oauthPub.y,
    SigningPubX: metadataSigningKey.point.x,
    SigningPubY: metadataSigningKey.point.y,
    metadataNonce: metadataPrivNonce,
    metadataSigningKey: metadataSigningKey.scalar,
    encryptedSeed: encDataBase64,
    finalUserPubKeyPoint: finalEd25519Key.point
  };
};
const generateSecp256k1KeyData = async scalarBytes => {
  const secp256k1Curve = metadataHelpers.getKeyCurve(constants.KEY_TYPE.SECP256K1);
  const N = secp256k1Curve.Point.CURVE().n;
  const scalar = metadataHelpers.bytesToNumberBE(scalarBytes);
  const randomNonce = metadataHelpers.bytesToNumberBE(metadataHelpers.generatePrivateKey(constants.KEY_TYPE.SECP256K1));
  const oAuthKey = metadataHelpers.mod(scalar - randomNonce, N);
  const oAuthPub = metadataHelpers.derivePubKey(secp256k1Curve, oAuthKey);
  const finalUserPub = metadataHelpers.derivePubKey(secp256k1Curve, scalar);
  return {
    oAuthKeyScalar: oAuthKey,
    oAuthPubX: oAuthPub.x,
    oAuthPubY: oAuthPub.y,
    SigningPubX: oAuthPub.x,
    SigningPubY: oAuthPub.y,
    metadataNonce: randomNonce,
    encryptedSeed: "",
    metadataSigningKey: oAuthKey,
    finalUserPubKeyPoint: finalUserPub
  };
};
const generateShares = async (ecCurve, keyType, serverTimeOffset, nodeIndexes, nodePubkeys, privKey) => {
  const keyData = keyType === constants.KEY_TYPE.ED25519 ? await generateEd25519KeyData(privKey) : await generateSecp256k1KeyData(privKey);
  const {
    metadataNonce,
    oAuthKeyScalar: oAuthKey,
    encryptedSeed,
    metadataSigningKey
  } = keyData;
  const threshold = ~~(nodePubkeys.length / 2) + 1;
  const degree = threshold - 1;
  const nodeIndexesBigInt = nodeIndexes.map(i => BigInt(i));
  const oAuthPub = metadataHelpers.derivePubKey(ecCurve, oAuthKey);
  const poly = metadataHelpers.generateRandomPolynomial(ecCurve, keyType, degree, oAuthKey);
  const shares = poly.generateShares(nodeIndexesBigInt);
  const nonceParams = metadataUtils.generateNonceMetadataParams(serverTimeOffset, "getOrSetNonce", metadataSigningKey, keyType, metadataNonce, encryptedSeed);
  const nonceData = metadataHelpers.bytesToBase64(metadataHelpers.utf8ToBytes(stringify(nonceParams.set_data)));
  const sharesData = [];
  const encPromises = [];
  for (let i = 0; i < nodeIndexesBigInt.length; i++) {
    const shareJson = shares[metadataHelpers.bigIntToHexPaddedString(nodeIndexesBigInt[i])].toJSON();
    if (!nodePubkeys[i]) {
      throw new Error(`Missing node pub key for node index: ${metadataHelpers.bigIntToHexPaddedString(nodeIndexesBigInt[i])}`);
    }
    const nodePubPoint = metadataHelpers.getSecp256k1().Point.fromAffine({
      x: metadataHelpers.toBigIntBE(nodePubkeys[i].X),
      y: metadataHelpers.toBigIntBE(nodePubkeys[i].Y)
    });
    encPromises.push(eccrypto.encrypt(nodePubPoint.toBytes(), metadataHelpers.hexToBytes(shareJson.share.padStart(64, "0"))));
  }
  const encShares = await Promise.all(encPromises);
  for (let i = 0; i < nodeIndexesBigInt.length; i += 1) {
    const shareJson = shares[metadataHelpers.bigIntToHexPaddedString(nodeIndexesBigInt[i])].toJSON();
    const encParams = encShares[i];
    const encParamsMetadata = common.encParamsBufToHex(encParams);
    const shareData = {
      encrypted_seed: keyData.encryptedSeed,
      final_user_point: keyData.finalUserPubKeyPoint,
      oauth_pub_key_x: metadataHelpers.bigIntToHexPaddedString(oAuthPub.x),
      oauth_pub_key_y: metadataHelpers.bigIntToHexPaddedString(oAuthPub.y),
      signing_pub_key_x: metadataHelpers.bigIntToHexPaddedString(keyData.SigningPubX),
      signing_pub_key_y: metadataHelpers.bigIntToHexPaddedString(keyData.SigningPubY),
      encrypted_share: encParamsMetadata.ciphertext,
      encrypted_share_metadata: encParamsMetadata,
      node_index: Number.parseInt(shareJson.shareIndex, 16),
      key_type: keyType,
      nonce_data: nonceData,
      nonce_signature: nonceParams.signature
    };
    sharesData.push(shareData);
  }
  return sharesData;
};

Object.defineProperty(exports, "encodeEd25519Point", {
    enumerable: true,
    get: function () { return metadataHelpers.encodeEd25519Point; }
});
Object.defineProperty(exports, "generateAddressFromPrivKey", {
    enumerable: true,
    get: function () { return metadataHelpers.generateAddressFromPrivKey; }
});
Object.defineProperty(exports, "generateAddressFromPubKey", {
    enumerable: true,
    get: function () { return metadataHelpers.generateAddressFromPubKey; }
});
Object.defineProperty(exports, "getEd25519ExtendedPublicKey", {
    enumerable: true,
    get: function () { return metadataHelpers.getEd25519ExtendedPublicKey; }
});
Object.defineProperty(exports, "getPostboxKeyFrom1OutOf1", {
    enumerable: true,
    get: function () { return metadataHelpers.getPostboxKeyFrom1OutOf1; }
});
Object.defineProperty(exports, "getSecp256k1PublicKeyFromAffinePoint", {
    enumerable: true,
    get: function () { return metadataHelpers.getSecp256k1PublicKeyFromAffinePoint; }
});
exports.generateEd25519KeyData = generateEd25519KeyData;
exports.generateSecp256k1KeyData = generateSecp256k1KeyData;
exports.generateShares = generateShares;
exports.isV2NonceResult = isV2NonceResult;
exports.stripHexPrefix = stripHexPrefix;
exports.toChecksumAddress = toChecksumAddress;
